struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = state_read::get("urls").unwrap_or_default();
        let urls: Vec<String> = raw
            .lines()
            .map(|l| l.trim())
            .filter(|l| !l.is_empty())
            .map(|l| l.to_string())
            .collect();
        if urls.is_empty() {
            // Contract: present(urls) must hold; refuse to emit an empty list.
            panic!("no subscriptions present in store");
        }
        SubscriptionList { urls }
    }
}

