use crate::aap::caps::state_read;

struct Node;

fn parse(raw: &str) -> Vec<String> {
    raw.split(|c: char| c.is_whitespace() || c == ',')
        .map(|s| s.trim_matches(|c: char| c == '[' || c == ']' || c == '"' || c == '\''))
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .collect()
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let keys = [
            "subscriptions",
            "urls",
            "feeds",
            "subscription-list",
            "subscription_list",
            "list",
            "",
        ];
        for k in keys {
            if let Some(raw) = state_read::get(k) {
                let urls = parse(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // Never trap: return an empty list if the store holds nothing.
        SubscriptionList { urls: Vec::new() }
    }
}

export!(Node);
